    pub(crate) fn compare_lin_tp_config(
        &self,
        other: &Document,
        a: &LinTpConfig,
        b: &LinTpConfig,
        path: &str,
    ) -> Result<(), String> {
        self.compare_tp_config(other, a.base(), b.base(), path)?;
        let list_a = a.get_tp_addresses();
        let list_b = b.get_tp_addresses();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TP_ADDRESSES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.tp_address.get(*x).ok_or_else(|| {
                format!("{path}.TP_ADDRESSES[{index}]: id not found in own arena")
            })?;
            let y = other.tp_address.get(*y).ok_or_else(|| {
                format!("{path}.TP_ADDRESSES[{index}]: id not found in other arena")
            })?;
            self.compare_tp_address(other, x, y, &format!("{path}.TP_ADDRESSES[{index}]"))?;
        }
        let list_a = a.get_tp_connections();
        let list_b = b.get_tp_connections();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TP_CONNECTIONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.lin_tp_connections.get(*x).ok_or_else(|| {
                format!("{path}.TP_CONNECTIONS[{index}]: id not found in own arena")
            })?;
            let y = other.lin_tp_connections.get(*y).ok_or_else(|| {
                format!("{path}.TP_CONNECTIONS[{index}]: id not found in other arena")
            })?;
            self.compare_lin_tp_connection(
                other,
                x,
                y,
                &format!("{path}.TP_CONNECTIONS[{index}]"),
            )?;
        }
        let list_a = a.get_tp_nodes();
        let list_b = b.get_tp_nodes();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TP_NODES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .lin_tp_nodes
                .get(*x)
                .ok_or_else(|| format!("{path}.TP_NODES[{index}]: id not found in own arena"))?;
            let y = other
                .lin_tp_nodes
                .get(*y)
                .ok_or_else(|| format!("{path}.TP_NODES[{index}]: id not found in other arena"))?;
            self.compare_lin_tp_node(other, x, y, &format!("{path}.TP_NODES[{index}]"))?;
        }
        Ok(())
    }

    pub(crate) fn compare_lin_tp_connection(
        &self,
        other: &Document,
        a: &LinTpConnection,
        b: &LinTpConnection,
        path: &str,
    ) -> Result<(), String> {
        self.compare_tp_connection(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_data_pdu_ref() != b.get_data_pdu_ref() {
            return Err(format!("{path}: DATA_PDU_REF mismatch"));
        }
        if a.get_flow_control_ref() != b.get_flow_control_ref() {
            return Err(format!("{path}: FLOW_CONTROL_REF mismatch"));
        }
        if a.get_lin_tp_n_sdu_ref() != b.get_lin_tp_n_sdu_ref() {
            return Err(format!("{path}: LIN_TP_N_SDU_REF mismatch"));
        }
        if a.get_multicast_ref() != b.get_multicast_ref() {
            return Err(format!("{path}: MULTICAST_REF mismatch"));
        }
        let list_a = a.get_receiver_refs();
        let list_b = b.get_receiver_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: RECEIVER_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.RECEIVER_REFS[{index}] mismatch"));
            }
        }
        if a.get_timeout_as() != b.get_timeout_as() {
            return Err(format!("{path}: TIMEOUT_AS mismatch"));
        }
        if a.get_timeout_cr() != b.get_timeout_cr() {
            return Err(format!("{path}: TIMEOUT_CR mismatch"));
        }
        if a.get_timeout_cs() != b.get_timeout_cs() {
            return Err(format!("{path}: TIMEOUT_CS mismatch"));
        }
        if a.get_transmitter_ref() != b.get_transmitter_ref() {
            return Err(format!("{path}: TRANSMITTER_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_lin_tp_node(
        &self,
        other: &Document,
        a: &LinTpNode,
        b: &LinTpNode,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_connector_ref() != b.get_connector_ref() {
            return Err(format!("{path}: CONNECTOR_REF mismatch"));
        }
        if a.get_drop_not_requested_nad() != b.get_drop_not_requested_nad() {
            return Err(format!("{path}: DROP_NOT_REQUESTED_NAD mismatch"));
        }
        if a.get_max_number_of_resp_pending_frames() != b.get_max_number_of_resp_pending_frames() {
            return Err(format!(
                "{path}: MAX_NUMBER_OF_RESP_PENDING_FRAMES mismatch"
            ));
        }
        if a.get_p2_max() != b.get_p2_max() {
            return Err(format!("{path}: P2_MAX mismatch"));
        }
        if a.get_p2_timing() != b.get_p2_timing() {
            return Err(format!("{path}: P2_TIMING mismatch"));
        }
        if a.get_tp_address_ref() != b.get_tp_address_ref() {
            return Err(format!("{path}: TP_ADDRESS_REF mismatch"));
        }
        Ok(())
    }

